            case 0x68: /* IN L, (C) */ Tick(4); { byte val = _ports?.In(BC) ?? 0xFF; if (5 != 6) L = val; FlagS = (val & 0x80) != 0; FlagZ = val == 0; FlagH = false; FlagPV = GetParity(val); FlagN = false; SetUndocumentedFlags(val); }; Tick(4); Tick(4); break;
